import json as J
# recompute attempt-5 style grid (cycle [2,5,0,5], rings 1-10, core 0)
def build(core_mode):
    g=[[0]*30 for _ in range(30)]
    for c in range(1,25): g[1][c]=5; g[25][c]=5
    for r in range(1,26): g[r][1]=5; g[r][24]=5
    cyc=[2,5,0,5]; r1,r2,c1,c2=2,24,2,23; i=0
    while (r2-r1+1)>=3 and (c2-c1+1)>=3:
        i+=1; col=cyc[(i-1)%4]
        if col:
            for cc in range(c1,c2+1): g[r1][cc]=col; g[r2][cc]=col
            for rr in range(r1,r2+1): g[rr][c1]=col; g[rr][c2]=col
        r1+=1; r2-=1; c1+=1; c2-=1
    if core_mode=='zero': pass
    elif core_mode=='five':
        for rr in range(r1,r2+1):
            for cc in range(c1,c2+1): g[rr][cc]=5
    elif core_mode=='two':
        for rr in range(r1,r2+1):
            for cc in range(c1,c2+1): g[rr][cc]=2
    return g
